export const money=n=>Math.round((n+Number.EPSILON)*100)/100;
export function positive(n,label='Valor',zero=true){n=Number(n);if(!Number.isFinite(n)||(zero?n<0:n<=0))throw Error(label+' inválido');return n}
export function effective({total,discount=0,freight=0,other=0,quantity,factor}){return (positive(total)-positive(discount)+positive(freight)+positive(other))/(positive(quantity,'Quantidade',false)*positive(factor,'Conversão',false))}
export function window3(reference){let end=new Date(reference+'T12:00:00Z');end.setUTCDate(1);let start=new Date(end);start.setUTCMonth(start.getUTCMonth()-3);return {start:start.toISOString().slice(0,10),end:end.toISOString().slice(0,10)}}
export function referenceCost(entries,id,reference){let w=window3(reference),e=entries.filter(x=>x.materialId===id&&x.received>=w.start&&x.received<w.end);return e.length?Math.max(...e.map(x=>x.cost)):null}
export function decide(state,ids,approved,actor){if(!actor?.trim())throw Error('Informe o responsável');let chosen=ids.map(id=>state.proposals.find(p=>p.id===id));if(chosen.some(p=>!p||p.status!=='pending'))throw Error('Proposta indisponível');for(let p of chosen){let m=state.materials.find(m=>m.id===p.materialId);if(!m)throw Error('Material ausente')}for(let p of chosen){p.old=state.materials.find(m=>m.id===p.materialId).cost;p.status=approved?'approved':'rejected';if(approved){let m=state.materials.find(m=>m.id===p.materialId);m.cost=p.cost;m.updated=new Date().toISOString()}state.audit.push({at:new Date().toISOString(),actor,action:p.status,proposalId:p.id,materialId:p.materialId,old:p.old,cost:p.cost})}return state}
export function installmentStatus(p,today){let paid=p.payments.reduce((s,x)=>s+x.amount,0);return paid>=p.amount?'pago':paid>0?'parcialmente pago':p.due<today?'vencido':'a vencer'}
export function pay(p,amount,date){amount=positive(amount,'Pagamento',false);if(amount>money(p.amount-p.payments.reduce((s,x)=>s+x.amount,0)))throw Error('Pagamento excede saldo');p.payments.push({amount,date});return p}
export function split(total,count,first){total=money(positive(total));count=positive(count,'Parcelas',false);if(!Number.isInteger(count)||count>120)throw Error('Parcelas inválidas');let cents=Math.round(total*100),base=Math.floor(cents/count);return Array.from({length:count},(_,i)=>{let d=new Date(first+'T12:00:00Z');if(isNaN(d))throw Error('Vencimento inválido');let day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+i);let last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return {id:crypto.randomUUID(),amount:(base+(i<cents%count?1:0))/100,due:d.toISOString().slice(0,10),payments:[]}})}
export function registerPurchase(s,p){if(p.key&&s.purchases.some(x=>x.key===p.key))throw Error('Nota já importada');if(!p.items.length)throw Error('Selecione itens');for(let x of p.items){if(!s.materials.some(m=>m.id===x.materialId))throw Error('Vincule os materiais');positive(x.factor,'Conversão',false);positive(x.quantity,'Quantidade',false)}s.purchases.push(p);for(let x of p.items){let cost=effective(x),m=s.materials.find(m=>m.id===x.materialId);s.entries.push({...x,cost,received:p.received,purchaseId:p.id,supplier:p.supplier});s.proposals.push({id:crypto.randomUUID(),materialId:m.id,old:m.cost,cost,status:'pending',at:p.received})}return s}
export function hourly(e){return (positive(e.salary)*(1+positive(e.thirteenth)/100+positive(e.vacation)/100)*(1+positive(e.charges)/100))/positive(e.hours,'Horas produtivas',false)}
export function quote(s,q){let length=positive(q.length,'Comprimento',false),elements=positive(q.elements,'Elementos',false);if(!Number.isInteger(elements))throw Error('Elementos deve ser inteiro');positive(q.diameter,'Diâmetro',false);let lines=q.lines.map(l=>{let m=s.materials.find(m=>m.id===l.materialId);if(!m||m.cost===null)throw Error('Material sem custo aprovado');let qty=positive(l.quantity);if(l.basis==='element')qty*=elements;if(l.basis==='length')qty*=length/1000*elements;return {name:m.description,category:m.category,quantity:qty,total:qty*m.cost}});let labor=s.steps.reduce((v,t)=>{let e=s.employees.find(e=>e.id===t.employeeId);if(!e)throw Error('Vincule funcionário às etapas');return v+Math.ceil(length/100)*elements*positive(t.minutes)/60*hourly(e)},0);let materials=lines.filter(l=>l.category!=='Acessório').reduce((v,l)=>v+l.total,0),accessories=lines.filter(l=>l.category==='Acessório').reduce((v,l)=>v+l.total,0);let factory=positive(q.factory),admin=positive(q.admin),cost=materials+accessories+labor+factory+admin,tax=positive(q.tax)/100,margin=positive(q.margin)/100;if(tax+margin>=1)throw Error('Tributos + margem devem ser menores que 100%');let price=q.mode==='markup'?cost*positive(q.markup,'Markup',false):cost/(1-tax-margin);let discount=positive(q.discount)/100;if(discount>1)throw Error('Desconto inválido');let sale=price*(1-discount),net=sale*(1-tax)-cost;return {lines,materials,accessories,labor,factory,admin,cost,price,sale,net,markup:cost?price/cost:0,gross:sale?(sale-materials-accessories-labor-factory)/sale:0,netMargin:sale?net/sale:0}}
export function parseNfe(xml,Parser=globalThis.DOMParser){let d=new Parser().parseFromString(xml,'application/xml');if(d.querySelector('parsererror'))throw Error('XML inválido');let get=(n,t)=>n.getElementsByTagNameNS('*',t)[0]?.textContent||'',num=(n,t)=>Number(get(n,t)||0),inf=d.getElementsByTagNameNS('*','infNFe')[0];if(!inf)throw Error('XML não é NF-e');let emit=d.getElementsByTagNameNS('*','emit')[0],key=inf.getAttribute('Id')?.replace(/^NFe/,'')||get(d,'chNFe');if(!/^\d{44}$/.test(key))throw Error('Chave NF-e inválida');return {key,number:get(d,'nNF'),issued:(get(d,'dhEmi')||get(d,'dEmi')).slice(0,10),supplier:get(emit,'xNome'),items:Array.from(d.getElementsByTagNameNS('*','det')).map(n=>({code:get(n,'cProd'),description:get(n,'xProd'),unit:get(n,'uCom'),quantity:num(n,'qCom'),total:num(n,'vProd'),discount:num(n,'vDesc'),freight:num(n,'vFrete'),other:num(n,'vOutro'),factor:1}))}}
